{{ config(
            materialized='table',
                post_hook={
                    "sql": "DROP TABLE IF EXISTS public.anveshan_flipkart_order_fulfilment_fact_items; CREATE TABLE public.anveshan_flipkart_order_fulfilment_fact_items AS SELECT CAST(order_date AS DATE) AS order_date, CAST(NULLIF(REPLACE(order_approval_date, \'\"\', \'\'), \'\') AS DATE) AS order_approval_date, REPLACE(REPLACE(sku, \'\"\', \'\'), \'sku:\', \'\') AS sku, order_id AS reference_code, order_id, CAST(NULLIF(order_cancellation_date, \'\') AS TIMESTAMP) AS cancellation_date, REPLACE(cancellation_reason,\'_\',\' \') AS cancellation_reason, CAST(NULLIF(order_ready_for_dispatch_on_date, \'\') AS TIMESTAMP) AS order_ready_for_dispatch_on_date, CAST(NULLIF(dispatch_after_date, \'\') AS TIMESTAMP) AS manifest_date, CAST(NULLIF(dispatch_by_date, \'\') AS TIMESTAMP) AS dispatch_date, CASE WHEN deliver_by_date = \'N\' THEN NULL ELSE CAST(deliver_by_date AS DATE) END AS delivery_date, CASE WHEN UPPER(pickup_logistics_partner) LIKE \'%cod%\' THEN \'cod\' ELSE \'prepaid\' END AS payment_mode, pickup_logistics_partner as courier, CAST(NULLIF(order_return_approval_date, \'\') AS date) AS return_approval_date, CAST(NULLIF(order_service_completion_date, \'\') AS date) AS order_service_completion_date, return_id, REPLACE(return_reason,\'_\',\' \') AS return_reason, REPLACE(return_sub_reason,\'_\',\' \') AS return_sub_reason, REPLACE(order_item_id,\'OI:\',\'\') AS order_item_id, REPLACE(product_title, \'\"\', \'\') AS product_name, fulfilment_type, fulfilment_source, REPLACE(order_item_status,\'_\',\' \') AS order_item_status, REPLACE(delivery_tracking_id, \'DTr:\', \'\') AS fk_awb FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, order_item_id ORDER BY order_return_approval_date DESC) AS rn FROM public.anweshan_fk_orders ) x WHERE rn = 1; DROP TABLE IF EXISTS public.anveshan_flipkart_fact_items; CREATE TABLE public.anveshan_flipkart_fact_items AS SELECT CASE WHEN s.\"Fulfilment Type\" = \'NON_FBF\' THEN \'Flipkart NON-FBF\' ELSE \'Flipkart FBF\' END AS shop_name, s.\"order id\", s.\"order id\" AS order_name, NULL AS customer_id, NULL AS phone, s.\"hsn code\" AS HSN_Code, s.\"order type\" AS payment_type, CAST(NULL AS VARCHAR) AS tags, s.\"order item id\" AS line_item_id, CAST(REPLACE(REPLACE(s.sku,\'\"\',\'\'),\'SKU:\',\'\') AS VARCHAR) AS SKU, REPLACE(s.FSN,\'\"\',\'\') AS product_id, CASE WHEN r.\"Event Sub Type\" = \'Return\' THEN 1 ELSE 0 END AS is_refund, CAST(NULL AS VARCHAR) AS city, CASE WHEN s.\"customer\'s delivery state\" = \'-\' THEN (CASE WHEN s.\"customer\'s billing state\" = \'-\' THEN NULL ELSE s.\"customer\'s billing state\" END) ELSE s.\"customer\'s delivery state\" END AS state, CASE WHEN s.\"customer\'s delivery pincode\" = \'-\' THEN (CASE WHEN s.\"customer\'s billing pincode\" = \'-\' THEN NULL ELSE s.\"customer\'s billing pincode\" END) ELSE s.\"customer\'s delivery pincode\" END AS pincode, REPLACE(s.\"product title/description\",\'\"\',\'\') AS PRODUCT_NAME, CAST(NULL AS VARCHAR) AS category, case when not(s.\"order date\" = \'-\') then (SUBSTRING(s.\"order date\", 1, 19)::TIMESTAMP)::date end as order_date, f.delivery_date, f.cancellation_date, f.manifest_date, f.dispatch_date, f.return_approval_date, f.return_reason, f.return_sub_reason, f.order_service_completion_date, f.order_item_status, f.return_id, f.fulfilment_type, f.fulfilment_source, f.cancellation_reason, f.payment_mode, CASE WHEN s.\"tds rate\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"tds rate\" AS DOUBLE PRECISION) ELSE NULL END AS tds_rate, CASE WHEN s.\"VAT Rate\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"VAT Rate\" AS DOUBLE PRECISION) ELSE NULL END AS VAT_Rate, CASE WHEN s.\"CGST Rate\" ~ \'^[+-]?[0-9]+(\.\d+)?$\' THEN CAST(s.\"CGST Rate\" AS DOUBLE PRECISION) ELSE NULL END AS CGST_Rate, CASE WHEN s.\"IGST Rate\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"IGST Rate\" AS DOUBLE PRECISION) ELSE NULL END AS IGST_Rate, CASE WHEN s.\"CST Amount\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"CST Amount\" AS DOUBLE PRECISION) ELSE NULL END AS CST_Amount, CASE WHEN s.\"TDS Amount\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"TDS Amount\" AS DOUBLE PRECISION) ELSE NULL END AS TDS_Amount, CASE WHEN s.\"VAT Amount\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"VAT Amount\" AS DOUBLE PRECISION) ELSE NULL END AS VAT_Amount, CASE WHEN s.\"CGST Amount\" ~ \'^[+-]?[0-9]+(\.\d+)?$\' THEN CAST(s.\"CGST Amount\" AS DOUBLE PRECISION) ELSE NULL END AS CGST_Amount, CASE WHEN s.\"IGST Amount\" ~ \'^[+-]?[0-9]+(\.\d+)?$\' THEN CAST(s.\"IGST Amount\" AS DOUBLE PRECISION) ELSE NULL END AS IGST_Amount, CASE WHEN s.\"Type of tax\" ~ \'^-?\d+(\.\d+)?$\' THEN CAST(s.\"Type of tax\" AS DOUBLE PRECISION) ELSE NULL END AS Type_of_tax, CASE WHEN s.\"Usual Price\" = \'NA\' THEN NULL WHEN s.\"Usual Price\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"Usual Price\" AS DOUBLE PRECISION) ELSE NULL END AS Usual_Price, s.\"Seller GSTIN\", ABS(COALESCE(CASE WHEN s.\"price after discount (price before discount-total discount)\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION) ELSE 0 END, 0)) AS line_item_sales, ABS(COALESCE(CASE WHEN s.\"Shipping Charges\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"Shipping Charges\" AS DOUBLE PRECISION) ELSE 0 END, 0)) AS shipping_price, ABS(COALESCE(CASE WHEN s.\"Item Quantity\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"Item Quantity\" AS DOUBLE PRECISION) ELSE 0 END, 0)) AS quantity, ABS(COALESCE(CASE WHEN s.\"Total TCS Deducted\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"Total TCS Deducted\" AS DOUBLE PRECISION) ELSE 0 END, 0)) AS tax, ABS(COALESCE(CASE WHEN s.\"price after discount (price before discount-total discount)\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION) ELSE 0 END, 0)) / NULLIF( COALESCE(CASE WHEN s.\"price after discount (price before discount-total discount)\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION) ELSE 0 END, 0) + COALESCE(CASE WHEN s.\"Total TCS Deducted\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"Total TCS Deducted\" AS DOUBLE PRECISION) ELSE 0 END, 0), 0) AS overall_tax_rate, ABS(COALESCE(CASE WHEN s.\"Total Discount\" ~ \'^[+-]?[0-9]+(\.\d+)?$\' THEN CAST(s.\"Total Discount\" AS DOUBLE PRECISION) END, 0)) AS discount, ABS(COALESCE(CASE WHEN s.\"Total Discount\" ~ \'^[+-]?[0-9]+(\.\d+)?$\' THEN CAST(s.\"Total Discount\" AS DOUBLE PRECISION) END, 0)) / NULLIF( 1 - (ABS(COALESCE(CASE WHEN s.\"Total TCS Deducted\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"Total TCS Deducted\" AS DOUBLE PRECISION) ELSE 0 END, 0)) / NULLIF( ABS(COALESCE(CASE WHEN s.\"Total TCS Deducted\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"Total TCS Deducted\" AS DOUBLE PRECISION) ELSE 0 END, 0)) + ABS(COALESCE(CASE WHEN s.\"price after discount (price before discount-total discount)\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION) ELSE 0 END, 0)), 0)), 0) AS discount_before_tax, ( ABS(COALESCE(CASE WHEN s.\"price after discount (price before discount-total discount)\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION) ELSE 0 END, 0)) - (ABS(COALESCE(CASE WHEN s.\"Total Discount\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"Total Discount\" AS DOUBLE PRECISION) ELSE 0 END, 0)) / NULLIF(1 - (ABS(COALESCE(CASE WHEN s.\"Total TCS Deducted\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"Total TCS Deducted\" AS DOUBLE PRECISION) ELSE 0 END, 0)) / NULLIF(ABS(COALESCE(CASE WHEN s.\"Total TCS Deducted\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"Total TCS Deducted\" AS DOUBLE PRECISION) ELSE 0 END, 0)) + ABS(COALESCE(CASE WHEN s.\"price after discount (price before discount-total discount)\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION) ELSE 0 END, 0)), 0)), 0)) ) AS gross_sales_before_tax, ABS(COALESCE(CASE WHEN s.\"price after discount (price before discount-total discount)\" ~ \'^[+-]?[0-9]+(\.[0-9]+)?$\' THEN CAST(s.\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION) ELSE 0 END, 0)) AS total_sales, CASE WHEN LOWER(s.\"is shopsy order?\") IN (\'true\', \'1\', \'yes\', \'y\') THEN \'Shopsy Order\' ELSE \'Flipkart Order\' END AS Order_Channel, s.\"Beneficiary Name\" AS name, CAST(NULL AS VARCHAR) AS email, f.fk_awb AS awb, f.courier, s.\"order shipped from (state)\" AS Order_Shipped_From_State, s.\"Warehouse ID\", s.\"Business Name\" FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY \"order item id\", \"order id\" ORDER BY \"buyer invoice id\" DESC) AS rn FROM public.anweshan_fk_sales WHERE lower(\"Event Sub Type\") like \'%sale%\' ) s LEFT JOIN public.anveshan_flipkart_order_fulfilment_fact_items f ON f.order_id = s.\"order id\" AND f.order_item_id = s.\"order item id\" LEFT JOIN ( SELECT *, ROW_NUMBER() OVER (PARTITION BY \"order item id\", \"order id\" ORDER BY \"buyer invoice id\" DESC) AS rn FROM public.anweshan_fk_sales WHERE lower(\"Event Sub Type\") like \'%return%\' ) r ON r.\"order id\" = s.\"order id\" AND r.\"order item id\" = s.\"order item id\" WHERE s.rn = 1 ;",
                    "transaction": true
                }
            ) }}
